    // Write the message length
    int length = schema.getSerializedSize(message);
    out.writeRawByte((byte) (length & 0xff));
    out.writeRawByte((byte) ((length >>> 8) & 0xff));
    out.writeRawByte((byte) ((length >>> 16) & 0xff));
    out.writeRawByte((byte) ((length >>> 24) & 0xff));

    // Serialize the message
    schema.writeTo(out, message, buffer);

    return length;
}

