    byte[] raw = schema.encode(message, buffer);
    int length = raw.length;
    out.write(ByteBuffer.allocate(4).putInt(length).array());
    out.write(raw);
    return length;
}

public int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = 0;
    buffer.clear();
    ProtoWriter pw = new ProtoWriter(buffer, out);
    try {
        pw.write(1, schema.writeAndMap(message), out);
        pw.flush();
        size = buffer.getSize();
        out.write(ByteBuffer.allocate(4).putInt(size).array());
    } catch (InvalidProtocolBufferException e) {
        throw new IllegalArgumentException(e);
    } finally {
        pw.dispose();
    }
    return size;
}

