private static  <T> int writeMessage(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    ByteArrayOutputStream bytes = new ByteArrayOutputStream();
    encode(buffer, message, schema);
    bytes.write(buffer.getByteArray(), 0, buffer.getSize());
    return out.write(bytes.toByteArray());
}

public static <T> int writeDelimitedTo(OutputStream out, T message, T schema, LinkedBuffer buffer) throws IOException {
    int startPos = buffer.writerIndex();
    int lenPos = buffer.writerIndex();
    buffer.writeVarint32(0, out);
    schema.writeTo(buffer, message);
    int endPos = buffer.writerIndex();
    int len = (endPos - startPos) - (endPos - lenPos);
    buffer.writeVarint32(len, out);
    return len;
}

