    List<TimeRange> timeRanges = new ArrayList<>();
    long rangeStart = start;
    long rangeEnd = end;
    while (rangeStart < rangeEnd) {
        // If the range end is greater than FETCH_DATA_DURATION, then split the range
        if (rangeEnd - rangeStart > FETCH_DATA_DURATION) {
            timeRanges.add(new TimeRange(rangeStart, rangeStart + FETCH_DATA_DURATION));
            rangeStart += FETCH_DATA_DURATION;
        } else {
            // Otherwise, add the entire range to the list and break the loop
            timeRanges.add(new TimeRange(rangeStart, rangeEnd));
            break;
        }
    }
    return timeRanges;
}

