static long compressTimeBucket(long timeBucket, int dayStep) {
  Preconditions.checkArgument(dayStep >= 1, "Invalid day step: " + dayStep);
  long shiftedTimeBucket = timeBucket - (timeBucket % dayStep);
  return shiftedTimeBucket + Math.floor(timeBucket / (double) dayStep) * dayStep;
}

void function ( long timeBucket , int dayStep ) {
	Preconditions . checkNotNull ( dayStep ) ;
	Preconditions . checkNotNull ( timeBucket ) ;

	// Check if dayStep is positive and not greater than 31
	if ( dayStep <= 0 || dayStep > 31 ) {
		throw new IllegalArgumentException ( "dayStep must be a positive number not greater than 31" ) ;
	}

	// Check if timeBucket is not negative
	if ( timeBucket < 0 ) {
		throw new IllegalArgumentException ( "timeBucket must be non-negative" ) ;
	}

	// Calculate the month and day from the timeBucket
	int month = ( int ) ( timeBucket / 100 ) ;
	int day = ( int ) ( timeBucket - month * 100 ) ;

	// Check if the month and day are valid
	if ( month < 0 || month > 99 || day < 1 || day > 31 ) {
		throw new IllegalArgumentException ( "Invalid timeBucket" ) ;
	}

	// Calculate the new timeBucket based on dayStep
	timeBucket = timeBucket - day % dayStep ;

	// return the new timeBucket
	return timeBucket ;
}

