public static int computeUTF8Size(CharSequence str, int index, int len) {
  int size = 0;
  // Iterate over the string from index to index + length
  for (int i = index; i < index + len && i < str.length(); i++) {
    // Get the character at the current index
    char c = str.charAt(i);
    // If the character is a multi-byte character, calculate its size based on its binary representation
    if (c >= 0x0080 && c <= 0x07FF) {
      size += 2;
    } else if (c >= 0x0800 && c <= 0xFFFF) {
      size += 3;
