private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
  // check if the strings are null
  if (str == null || suffix == null) {
    return false;
  }
  // check if the strings are empty
  if (str.isEmpty() || suffix.isEmpty()) {
    return false;
  }
  // get the length of the suffix
  int suffixLen = suffix.length();
  // check if the suffix length is less than or equal to the string length
  if (suffixLen > str.length()) {
    return false;
  }
  // get the substring of the string to compare
  String subStr = str.substring(str.length() - suffixLen);
  // check if the substring is equal to the suffix
  if (subStr.equals(suffix)) {
    return true;
  }
  // check if the compare should ignore case
  if (ignoreCase) {
    // compare the strings ignoring case
    return subStr.equalsIgnoreCase(suffix);
  }
  // the strings are not equal
  return false;
}

