public int digitValue(final char c) {
    int d = (int)c;
    if (d >= 97 && d <= 102) { // a-f
        return d - 87;
    } else if (d >= 65 && d <= 70) { // A-F
        return d - 55;
    } else if (d >= 48 && d <= 57) { // 0-9
        return d - 48;
    } else {
        throw new IllegalArgumentException("Invalid digit: " + c);
