    // Collect all the buffers and their data
    List<ByteBuffer> buffers = new ArrayList<>();
    for (ByteBuffer buffer : MEMBERS) {
        if (buffer != null && buffer.hasArray()) {
            buffers.add(buffer);
        }
    }
    if (buffers.isEmpty()) {
        return EMPTY_ARRAY;
    }

    // Calculate the total size and create the output buffer
    int totalSize = buffers.stream().mapToInt(Buffer::capacity).sum();
    ByteBuffer outputBuffer = ByteBuffer.allocate(totalSize);

    // Copy the data from each buffer to the output buffer
    for (ByteBuffer buffer : buffers) {
        outputBuffer.put(buffer.array());
    }

    // Return the output buffer as a byte array
    return outputBuffer.array();
}

