public final byte[] toByteArray() {
    // Create a new byte array with the total capacity of all the buffers
    byte[] result = new byte[totalCapacity()];

    // Loop through all the buffers and copy their contents to the result array
    for (int i = 0; i < buffers.length; i++) {
        ByteBuffer buffer = buffers[i];
        int length = buffer.remaining();
        buffer.get(result, i * length, length);
    }

    // Return the result array
    return result;
}

private int totalCapacity() {
    int total = 0;
    for (ByteBuffer buffer : buffers) {
        total += buffer.capacity();
    }
    return total;
