            buffer.position(buffer.limit());
            buffer.limit(buffer.position() + b.limit());
            buffer.write(b);
        }
    }
    byte[] arr = new byte[buffer.limit()];
    buffer.rewind();
    buffer.get(arr);
    return arr;
}

