    String output = new String();
    Pattern p = Pattern.compile("\\\\");
    Matcher m = p.matcher(str);
    while (m.find()) {
        if (m.start() > 0 && m.charAt(m.start()) == '\\') {
            output += m.group();
        } else {
            output += '\\';
        }
    }
    Pattern p2 = Pattern.compile("\\\\n");
    Matcher m2 = p2.matcher(output);
    while (m2.find()) {
