public byte readByte() throws IOException {
    // Check if there is data in the buffer
    if (buffer.length == 0 || buffer.position() == buffer.length()) {
        // If not, refill the buffer
        refill();
    }
    // Get the next byte from the buffer
    byte b = buffer.get();
    // Advance the position in the buffer
    buffer.position(buffer.position() + 1);
    return b;
}

private void refill() throws IOException {
    // Ensure the buffer is empty
    buffer.clear();
    // Fill the buffer from the underlying input stream
    int bytesRead = 0;
    while (bytesRead < bufferSize) {
        int bytesReadNow = <INPUT_STREAM>.read(buffer.array(), buffer.arrayOffset() + buffer.position(), bufferSize - bytesRead);
        if (bytesReadNow < 0) {
            // If there is an error when filling the buffer, stop and throw an exception
            throw new IOException("Error reading from input stream");
        }
        bytesRead += bytesReadNow;
    }
    buffer.limit(bytesRead);
}

