private String unescapeId(String input) {
    // Check if the input is valid
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input cannot be null or empty");
    }

    // Check if the input contains any escaped characters
    if (!input.contains("\\")) {
        return input;
    }

    // Unescape the input
    String output = "";
    char[] chars = input.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        if (chars[i] == '\\') {
            char nextChar = (i + 1 < chars.length) ? chars[i + 1] : null;
            if (nextChar == '\\') {
                output += "\\";
                i++;
            } else if (nextChar != null) {
                output += nextChar;
                i++;
            } else {
                throw new IllegalArgumentException("Input contains an invalid escape sequence");
            }
        } else {
            output += chars[i];
        }
    }

    return output;
}

