public static String base64Decode(final String s) {
    int length = s.length();
    if (length % 4 != 0) {
        throw new IllegalArgumentException("String length must be a multiple of 4");
    }

    byte[] bytes = new byte[length / 4];
    for (int i = 0, j = 0; i < length; i += 4, j++) {
        bytes[j] = (byte) ((decodeOctet(s.charAt(i)) << 2) + (decodeOctet(s.charAt(i + 1)) >> 4));
        if (i + 2 < length) {
            bytes[j] |= (byte) ((decodeOctet(s.charAt(i + 2)) << 4) + (decodeOctet(s.charAt(i + 3))));
        }
    }

    return new String(bytes, StandardCharsets.UTF_8);
}

