public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str instanceof String) {
        return ((String) str).regionMatches(index, substring, 0, substring.length());
    } else if (str instanceof StringBuilder) {
        return ((StringBuilder) str).regionMatches(index, substring, 0, substring.length());
    } else {
        return false;
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (index < 0 || index > str.length() - substring.length()) {
        return false;
    }
    int substringLength = substring.length();
    for (int i = 0; i < substringLength; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // return true if the given string matches the given substring at the given index, false otherwise
    return str.subSequence(index, index + substring.length()).equals(substring);
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null) {
        return false;
    }
    if ((index < 0) || (index >= str.length())) {
        return false;
    }
    if (substring == null) {
        return false;
    }
    if (substring.length() == 0) {
        return true;
    }
    if (substring.length() > str.length() - index) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

