    if (str == null || substring == null || index < 0 || index > str.length() || substring.length() > str.length() - index) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

